	           ) A

			 ORDER BY ${sort_column}

	   ) AA
 LIMIT ${pageSize} OFFSET ${(page-1)*pageSize}

mapper.select:
/* comm-mapper.xml selectAuthNumCheck SMS 인증번호 조회  */
SELECT mb_id       /* 회사코드    VARCHAR2(20) */
     , emp_cd      /* 사원코드    VARCHAR2(20) */
     , auth_num    /* SMS인증번호 VARCHAR2(40) */
     , in_dtm      /* 전송일시    TIMESTAMP    */
  FROM tbsy_login_auth_num /* [SY][시스템] 로그인 SMS인증번호관리 */
 WHERE mb_id = #{mb_id}
   AND emp_cd = #{emp_cd}

mapper.delete:
/* comm-mapper.xml deleteAuthNum SMS 인증번호 삭제  */
DELETE FROM tbsy_login_auth_num /* [SY][시스템] 로그인 SMS인증번호관리 */
 WHERE mb_id = #{mb_id}
   AND emp_cd = #{emp_cd}
